import re, json

def parse_llm_structured_output(raw_response: str) -> dict | None:
    fence_match = re.search(r'```(?:json)?\s*([\s\S]*?)```', raw_response)
    if fence_match:
        try:
            return json.loads(fence_match.group(1).strip())
        except json.JSONDecodeError:
            pass
    xml_match = re.search(r'<json>(.*?)</json>', raw_response, re.DOTALL)
    if xml_match:
        try:
            return json.loads(xml_match.group(1).strip())
        except json.JSONDecodeError:
            pass
    try:
        return json.loads(raw_response.strip())
    except json.JSONDecodeError:
        return None

